interface PaymentProcessor { charge(amount: number): Promise<Receipt>; }

class StripeAdapter implements PaymentProcessor {
  constructor(private readonly stripe: StripeApi) {}

  async charge(amount: number): Promise<Receipt> {
    const charge = await this.stripe.createCharge({ amount_cents: Math.round(amount * 100) });
    return { id: charge.id, ok: charge.status === 'succeeded' };
  }
}

